<?php
namespace Azuriom\Plugin\GamingHubCore\Controllers\Admin; use Azuriom\Http\Controllers\Controller; use Azuriom\Plugin\GamingHubCore\Contracts\PublicDataPolicyResolver; use Azuriom\Plugin\GamingHubCore\Http\Requests\SaveServerPublicDataRequest; use Azuriom\Plugin\GamingHubCore\Models\Game; use Azuriom\Plugin\GamingHubCore\Models\PublicDataPolicy; use Azuriom\Plugin\GamingHubCore\Models\Server; use Azuriom\Plugin\GamingHubCore\Services\NormalizedDataKeys; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\DB; use Illuminate\View\View;
final class ServerPublicDataController extends Controller { public function __construct(private PublicDataPolicyResolver $resolver){} public function edit(Game $game,Server $server):View{$this->owned($game,$server);$rows=PublicDataPolicy::query()->where('server_id',$server->id)->get()->keyBy('stat_key');$effective=[];foreach(NormalizedDataKeys::GENERIC as $k)$effective[$k]=$this->resolver->effective($server,$k);return view('gaming-hub-core::admin.servers.public-data',compact('game','server','rows','effective')+['keys'=>NormalizedDataKeys::GENERIC]);} public function update(SaveServerPublicDataRequest $r,Game $game,Server $server):RedirectResponse{$this->owned($game,$server);DB::transaction(function()use($r,$server){foreach(NormalizedDataKeys::GENERIC as $k)PublicDataPolicy::query()->updateOrCreate(['server_id'=>$server->id,'stat_key'=>$k],['visibility'=>($r->validated()['visibility'][$k]??'inherit'),'attribution'=>($r->validated()['attribution'][$k]??'inherit')]);});return back()->with('success',trans('gaming-hub-core::admin.settings.saved'));} private function owned(Game $g,Server $s):void{abort_unless($s->game_id===$g->id,404);} }
